P = [
 dict(pmid='42911598', doi='10.1093/annweh/wxag089', journal='Ann Work Expo Health', short='Sim real-time dust monitor bias gravimetric meta-analysis 2026', title='Systematic bias in real-time dust monitoring: a meta-analysis of measurement discrepancy and its implications for occupational exposure assessment.', sub=corpus.SENS, design='Systematic review + random-effects meta-analysis', pm='Optical real-time dust monitors (DustTrak, SidePak, pDR) vs gravimetric samplers', geo='Global / multi-region (occupational literature 2010-2025)', endpoint='Log response ratio of geometric-mean concentration, RTM vs gravimetric', tier='A', n='PRISMA meta-analysis of 112 occupational studies; 96 paired RTM-gravimetric comparisons pooled in a three-level random-effects model. Professional photometers read 36% high on average: pooled lnR 0.31 (0.25-0.37), I2 78.4%, prediction interval 0.11-0.63. Factory-calibrated units read 43% high, site-calibrated units 13% high; site-specific calibration was the strongest moderator (beta -0.24, P<0.001), followed by log GSD of the size distribution (beta 0.15) and RH (beta 0.002 per %). No eligible study compared sub-$500 sensors against gravimetry. Limitation: geometric-mean ratios from heterogeneous aerosols and campaign lengths; the prediction interval never crosses zero but its width means a single uncalibrated deployment can be off by 12-88%. Relevance: high - the size-distribution and RH moderators are the same terms LCS calibration models need, now with a pooled prior.'),
 dict(pmid='42916414', doi='10.1021/acs.est.6c03046', journal='Environ Sci Technol', short='Wang electret HVAC filter charge neutralisation wildfire smoke 2026', title='Charge-Driven Degradation of Residential Electret HVAC Filters under Wildfire Smoke Exposure.', sub=corpus.OCC, design='Materials / filtration', pm='Flaming/smouldering wood smoke, prescribed-burn smoke and soot challenges; EPA monitor PM2.5 for model inputs', geo='United States (laboratory, prescribed burns, regional wildfire scenario)', endpoint='Electret filter fractional efficiency vs loading; modelled indoor PM2.5 protection', tier='A', n='Laboratory flaming and smouldering wood smoke, field sampling at prescribed burns and controlled soot challenges on residential electret HVAC filters. Filtration efficiency collapsed at particle loadings far below those that raise pressure drop; the driver was soot-rich particles neutralising electret charge irreversibly, not mechanical clogging or organic-aerosol deposition. Built into a dynamic indoor model driven by EPA monitor data for a regional wildfire event, effective filter life fell from months to days at moderate outdoor PM2.5, with protection varying by building and ventilation. No efficiency numbers are given in the abstract. Limitation: few filter products and smoke types; charge loss in the field depends on soot fraction, which varies by fire stage. Relevance: high - indoor/outdoor LCS pairs can detect the efficiency collapse that pressure-based replacement rules miss.'),
 dict(pmid='42914075', doi='10.1016/j.envres.2026.125963', journal='Environ Res', short='Meng traffic noise air pollution lung function randomised crossover 2026', title='Independent and interactive effects of traffic-related noise and air pollution on lung function: A randomized crossover study in healthy young adults.', sub=corpus.RESP, design='Randomised crossover trial', pm='Roadside PM1, PM2.5, PM10, O3, NO2 and noise during evening rush hour', geo='China (urban roadside)', endpoint='FVC, FEV1, FEV1/FVC, FEF25-75 and distal flows', tier='A', n='Randomised crossover with four exposure conditions (noise and air pollution separated by intervention) in 51 healthy young adults beside a busy road at evening rush hour; pollutants and noise measured each session, mixed models adjusted for age, sex and BMI. Per 10 ug/m3 PM10, FEF75 fell 0.215 L/s; per 10 ug/m3 O3, 0.224 L/s. Noise independently reduced dynamic ventilatory indices, and exploratory interaction terms suggested noise amplified PM1- and PM2.5-associated FEV1 and small-airway decrements. No CIs in the abstract. Limitation: the four interventions are not described in the abstract and exposure conditions cannot be blinded, and pollutant contrasts within a single rush-hour session are small and collinear, so the interaction findings are hypothesis-generating. Relevance: medium - co-located acoustic and PM nodes are needed to separate the two stressors.'),
 dict(pmid='42919280', doi='10.1186/s12889-026-28800-4', journal='BMC Public Health', short='Liu PM2.5 components small for gestational age IVF Guangzhou 2026', title='Maternal exposure to PM(2.5) and its components and risk of small for gestational age in women undergoing in vitro fertilization: a propensity score-matched case-control study in Guangzhou, China.', sub=corpus.REPR, design='Case-control study', pm='Trimester-averaged PM2.5 and SO4, NO3, NH4, OM, BC (gridded estimates at residence)', geo='China (Guangzhou)', endpoint='Small for gestational age in IVF pregnancies', tier='B', n='Propensity-score-matched case-control within 1,459 IVF conceptions in Guangzhou: 166 SGA cases matched 1:1. Whole-pregnancy PM2.5 OR 1.124 (1.015-1.245); second trimester 1.082 (1.005-1.165); third trimester 1.075 (1.002-1.154); the exposure increment is not given in the abstract. SO4, OM and BC were positively associated; mixture models ranked nitrate as the dominant driver, and no subgroup reached significance. Limitation: 332 matched women give lower CI bounds within 0.2-1.5% of the null across many component-by-window tests, with no multiplicity correction reported; the component estimates come from a modelled product whose component-specific error is unknown. Relevance: low-medium - component attribution here rests on modelled speciation that sensor networks cannot supply.'),
]
